<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
foreach(['database','auth','owners','patients','attention','sanitary-events']as$file)require __DIR__.'/../server/'.$file.'.php';
function assertSanitary(bool $value):void{if(!$value)throw new RuntimeException('ASSERTION_FAILED');}
function rejectSanitary(callable $fn,string $reason):void{try{$fn();}catch(\VetCare\AccessError$e){assertSanitary($e->reason===$reason);return;}throw new RuntimeException('EXPECTED_REJECTION');}
try{
 $db=\VetCare\centralDatabase();foreach(['001_auth','002_owners','003_patients','004_consultations','005_sanitary_events']as$migration){$sql=file_get_contents(__DIR__.'/../database/mariadb/'.$migration.'.sql');$sql=str_replace('CREATE TABLE IF NOT EXISTS','CREATE TEMPORARY TABLE',$sql);$sql=preg_replace('/^\s*FOREIGN KEY[^\r\n]*\r?\n/m','',$sql);$sql=preg_replace('/,\s*\)/',"\n)",$sql);foreach(explode(';',$sql)as$statement)if(trim($statement)!=='')$db->exec($statement);}
 $actor=\VetCare\createUser($db,['username'=>'test-vet','name'=>'Prueba temporal','role'=>'veterinario','password'=>'clave-temporal-de-prueba']);$db->beginTransaction();$owner=\VetCare\saveOwner($db,$actor,['name'=>'Temporal','operationId'=>\VetCare\uuid()],true);$patient=\VetCare\savePatient($db,$actor,['operationId'=>\VetCare\uuid(),'name'=>'Temporal','species'=>'Perro','ownerId'=>$owner['id']],true);$db->commit();
 $save=function(array $input,bool $create)use($db,$actor):array{$db->beginTransaction();try{$result=\VetCare\saveSanitaryEvent($db,$actor,$input,$create);if($result['saved'])$db->commit();else$db->rollBack();return$result;}catch(Throwable$e){$db->rollBack();throw$e;}};
 $vaccine=['kind'=>'vacuna','patientId'=>$patient['id'],'patientVersion'=>1,'operationId'=>\VetCare\uuid(),'date'=>'2026-01-01','product'=>'Vacuna temporal','application'=>'Refuerzo','nextDate'=>'2026-06-01'];$first=$save($vaccine,true);assertSanitary($first['saved']&&$first['event']['nextDate']==='2026-06-01');assertSanitary($save($vaccine,true)===$first);assertSanitary((int)$db->query('SELECT COUNT(*) FROM vc_vaccinations')->fetchColumn()===1);rejectSanitary(fn()=>$save([...$vaccine,'product'=>'Otra'],true),'OPERATION_REUSED');
 $corrected=$save([...$vaccine,'operationId'=>\VetCare\uuid(),'id'=>$first['event']['id'],'version'=>1,'nextDate'=>null],false);assertSanitary($corrected['event']['version']===2&&$corrected['event']['createdBy']===$first['event']['createdBy']);$snapshot=json_decode($db->query('SELECT snapshot FROM vc_vaccination_versions WHERE version=1')->fetchColumn(),true);assertSanitary($snapshot['nextDate']==='2026-06-01');rejectSanitary(fn()=>$save([...$vaccine,'operationId'=>\VetCare\uuid(),'id'=>$first['event']['id'],'version'=>1],false),'SANITARY_EVENT_CONFLICT');
 $deworming=$save(['kind'=>'desparasitacion','patientId'=>$patient['id'],'patientVersion'=>1,'operationId'=>\VetCare\uuid(),'date'=>'2026-01-02','product'=>'Producto temporal','weight'=>'0,001','nextDate'=>'2026-07-01'],true);assertSanitary($deworming['event']['weight']===1);$invalid=$save(['kind'=>'desparasitacion','patientId'=>$patient['id'],'patientVersion'=>1,'operationId'=>\VetCare\uuid(),'date'=>'2026-01-02','product'=>'Producto temporal','nextDate'=>'2025-12-31'],true);assertSanitary(!$invalid['saved']);
 $vaccines=\VetCare\listSanitaryEvents($db,$actor,['patientId'=>$patient['id'],'kind'=>'vacuna','page'=>'1']);$dewormings=\VetCare\listSanitaryEvents($db,$actor,['patientId'=>$patient['id'],'kind'=>'desparasitacion','page'=>'1']);assertSanitary(count($vaccines['events'])===1&&count($dewormings['events'])===1&&$dewormings['events'][0]['weight']===1);
 $db->beginTransaction();\VetCare\savePatient($db,$actor,[...$patient,'operationId'=>\VetCare\uuid(),'active'=>false],false);$db->commit();rejectSanitary(fn()=>$save([...$vaccine,'operationId'=>\VetCare\uuid(),'patientVersion'=>2],true),'PATIENT_INACTIVE');assertSanitary($save([...$vaccine,'operationId'=>\VetCare\uuid(),'id'=>$first['event']['id'],'version'=>2,'patientVersion'=>2,'nextDate'=>'2026-08-01'],false)['saved']);rejectSanitary(fn()=>\VetCare\listSanitaryEvents($db,['role'=>'otro'],['patientId'=>$patient['id'],'kind'=>'vacuna','page'=>'1']),'FORBIDDEN');
 echo "MariaDB: vacunaciones, desparasitaciones, reintentos, correcciones, versiones, próxima fecha y paciente inactivo comprobados en tablas temporales.\n";
}catch(Throwable){fwrite(STDERR,"No se completó la prueba real de eventos sanitarios. Revisa db:check y permisos de tablas temporales.\n");exit(1);}
